package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.io.*;
final class ProgramLab{
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-program-lab",0);}
 static String hash(Map<String,String> files)throws Exception{return JavaMethodEditor.hash(new JSONObject(files).toString());}
 static String create(Context c,String request)throws Exception{ProgramPlan plan=ProgramPlan.request(request);NaturalCoding.project(c);Map<String,String> core=plan.core();JSONObject before=new JSONObject();for(String file:core.keySet())before.put(file,JavaProject.source(c,file));JavaChat.phase("Compilando programa de varios pasos y clases…");OnDeviceJava.Build build=OnDeviceJava.compileSources(c,plan.candidate());long seed=new java.security.SecureRandom().nextLong();JSONObject spec=new JSONObject().put("plan",plan.json()).put("seed",seed);android.os.Bundle proof=JavaTrial.request(c,build.jar,spec.toString(),"pipeline",64);JavaProject.stageBatch(c,core);JSONObject row=new JSONObject().put("plan",plan.json()).put("jar",build.jar.getAbsolutePath()).put("jarHash",ProjectRuntime.digest(build.jar)).put("sourceHash",hash(core)).put("before",before).put("base",JavaProject.fingerprint(c)).put("tests",64).put("seed",seed).put("instruction",request);if(!prefs(c).edit().putString("candidate",row.toString()).commit())throw new IOException("La copia quedó preparada, pero falta su registro.");NaturalCoding.prefs(c).edit().putString("target","program").putString("receipt","Programa de "+plan.steps.length()+" pasos comprobado en64 casos generados.").commit();LearningJournal.add(c,"verified_program",request,"Compiló y pasó64 casos generados en otro proceso; no es una prueba de inteligencia general.",64);return "Preparé un programa Java de "+plan.steps.length()+" pasos coordinados.\nArchivos modificados: JavaAlgorithm.java y ProgramKernel.java; biblioteca: ProgramSupport.java.\nCompilación real y64 casos generados después de compilar, ejecutados en otro proceso.\nLa copia está preparada. Podés decir ‘probalo con: …’, ‘deshace ese cambio’ o ‘incorporalo a la app’. El código instalado cambia al actualizar Banana.apk.";}
 static JSONObject candidate(Context c)throws Exception{String raw=prefs(c).getString("candidate","");if(raw.isEmpty())throw new IllegalArgumentException("Todavía no hay un programa preparado.");JSONObject row=new JSONObject(raw);ProgramPlan plan=ProgramPlan.read(row.getJSONObject("plan"));if(!hash(plan.core()).equals(row.getString("sourceHash")))throw new IOException("La fuente canónica cambió.");for(Map.Entry<String,String> e:plan.core().entrySet())if(!JavaProject.source(c,e.getKey()).equals(e.getValue()))throw new IOException("La copia cambió después de las pruebas.");return row;}
 static String test(Context c,String input)throws Exception{if(input.length()>1024)throw new IllegalArgumentException("Entrada demasiado larga.");JSONObject row=candidate(c);File jar=new File(row.getString("jar"));if(!jar.getCanonicalPath().startsWith(OnDeviceJava.home(c).getCanonicalPath()+File.separator)||jar.canWrite()||!row.getString("jarHash").equals(ProjectRuntime.digest(jar)))throw new IOException("El archivo compilado cambió.");return "Resultado del programa: "+OnDeviceJava.load(c,jar).getClassLoader().loadClass("com.bananalab.patch.ProgramKernel").getMethod("apply",String.class).invoke(null,input);}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=NaturalCoding.normalize(input);String task=Knowledge.normalize(NaturalCoding.polite(input)).replaceFirst("^(?:crea|creame|haceme|programa|genera|generame) (?:un |una )?(?:metodo|funcion|algoritmo|programa)(?: java)? (?:que |para )?","");boolean explicit=q.startsWith("programa estos pasos "),create=explicit||!task.equals(Knowledge.normalize(NaturalCoding.polite(input)))&&task.matches("(?s).*(?:transforma|transforme|conserva|conserve|orden|duplicad|multiplic|cuadrad|mayores|menores|cada elemento|sin espacios).*"),last=NaturalCoding.prefs(c).getString("target","").equals("program"),test=last&&q.matches("(?:probalo|pruebalo|proba|prueba)(?: con|:).*"),undo=last&&q.matches("(?:deshace|deshaci|reverti|revierte) (?:ese|el ultimo|este) cambio");if(!create&&!test&&!undo)return null;JavaChat.owner=Thread.currentThread();try{String text;if(create)text=create(c,explicit?input.substring(input.indexOf(':')+1).trim():task);else if(test)text=test(c,NaturalCoding.payload(input));else{JSONObject row=candidate(c);if(!row.getString("base").equals(JavaProject.fingerprint(c)))throw new IOException("La base cambió.");JSONObject before=row.getJSONObject("before");Map<String,String> files=new LinkedHashMap<>();Iterator<String> it=before.keys();while(it.hasNext()){String key=it.next();files.put(key,before.getString(key));}JavaProject.stageBatch(c,files);NaturalCoding.prefs(c).edit().remove("target").commit();text="Recuperé los dos archivos anteriores de la copia. El programa instalado se conserva.";}return MobileCore.say(c,text,"app_ajuste");}catch(Exception e){if(create)try{LearningJournal.add(c,"rejected_candidate",task,AndroidRepair.summary(e),0);}catch(Exception ignored){}return MobileCore.say(c,"No completé un programa nuevo: "+AndroidRepair.summary(e),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
